parameters.customBody:
={{ (() => {
  const s = $json;
  const list = v => String(v || '').split(',').map(x => x.trim()).filter(Boolean);
  return JSON.stringify({
    keywords: list(s.topics),
    keywordsOnly: false,
    onlyOpenDeadlines: true,
    maxRequests: s.maxRequests,
    sources: list(s.sources),
    onlyNewRequests: true
  });
})() }}

parameters.text:
=EXPERT
Name: {{ $('Set your profile').first().json.yourName }}
Role: {{ $('Set your profile').first().json.yourRole }}
What makes them quotable: {{ $('Set your profile').first().json.yourCredentials }}
Topics they claim: {{ $('Set your profile').first().json.topics }}

JOURNALIST REQUEST
Headline: {{ $json.title }}
Asked by: {{ $json.requesterName || $json.authorHandle || 'not stated' }} ({{ $json.requesterType || 'unknown role' }})
Section: {{ $json.industry || 'not stated' }}
Deadline: {{ $json.deadlineText || 'not stated' }}
What they need: {{ $json.summary || $json.title }}

=EXPERT
Name: {{ $('Set your profile').first().json.yourName }}
Role: {{ $('Set your profile').first().json.yourRole }}
What makes them quotable: {{ $('Set your profile').first().json.yourCredentials }}

JOURNALIST REQUEST
Headline: {{ $json.Request }}
Asked by: {{ $json.Requester }}
What they need: {{ $json['What they need'] }}
Deadline: {{ $json.Deadline }}

LEAD WITH THIS ANGLE
{{ $json.Angle }}

={{ (() => {
const esc = s => String(s ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const r = $('Format the row').item.json;
const draft = String($json.text || '').trim();
const who = [r['Requester'], r['Requester type']].filter(Boolean).join(' \u00b7 ');
const when = r['Deadline'] === 'not stated' ? 'no deadline stated'
  : r['Deadline'] + (r['Days left'] === '' ? '' : ' (' + r['Days left']
    + (Number(r['Days left']) === 1 ? ' day left)' : ' days left)'));
return '\ud83d\udcf0 <b>' + esc(String(r['Request']).slice(0, 110)) + '</b>\n'
  + esc(who) + (who ? ' \u00b7 ' : '') + esc(when) + ' \u00b7 match ' + r['Score'] + '/100\n'
  + (String(r['Angle'] || '').trim() ? '\ud83c\udfaf ' + esc(r['Angle']) + '\n\n' : '\n')
  + '<b>Draft reply</b>\n<pre>' + esc(draft) + '</pre>\n\n'
  + '\u27a1 <a href="' + r['Respond URL'] + '">Send it here</a>';
})() }}
